#!/usr/bin/env python

"""
Compute physical diagnostic spectra from the Zheng N1000 histogram aerosol state.

The input is the histogram file already generated by `extract_X.py`:
    aero_samples_Zheng_N1000.nc

This script no longer rebuilds histograms from `aero_processed_*.nc`.
Instead, it reads:
    - M: [samples, species, bins]
    - N: [samples, bins]

The diagnostic-spectrum implementation is embedded in this file, and the output is:
    aero_samples_Zheng_N1000_diagnoistics.nc
"""

