def get_chemsubidx(
    chem_inc: Optional[List[str]],
    chem_exc: Optional[List[str]],
    chem_species: List[str],
    n_chem: int,
) -> Tuple[List[int], int]:
    assert len(chem_species) == n_chem
    if (chem_inc is not None) and (chem_exc is not None):
        raise ValueError(f"chem_inc and chem_exc cannot both be specified: chem_inc={chem_inc}, chem_exc={chem_exc}")
    if chem_inc is not None:
        chem_inc_lst = [chem_inc] if isinstance(chem_inc, str) else chem_inc
        i_subchms = [i for i, chem in enumerate(chem_species) if chem in chem_inc_lst]
        return i_subchms, len(i_subchms)
    if chem_exc is not None:
        chem_exc_lst = [chem_exc] if isinstance(chem_exc, str) else chem_exc
        i_subchms = [i for i, chem in enumerate(chem_species) if chem not in chem_exc_lst]
        return i_subchms, len(i_subchms)
    return list(range(n_chem)), n_chem


def get_vwakappa(
    v_chmprt: torch.Tensor,
    kappa_chm: torch.Tensor,
    n_chem: int,
    void_kappa: float,
    i_chmsub: Optional[List[int]] = None,
) -> torch.Tensor:
    assert not v_chmprt.isnan().any()
    assert not kappa_chm.isnan().any()
    if i_chmsub is None:
        v_chmprtsub = v_chmprt
        kappa_chmsub = kappa_chm
    else:
        v_chmprtsub = v_chmprt[..., i_chmsub]
        kappa_chmsub = kappa_chm[..., i_chmsub]
    v_prtsub = v_chmprtsub.sum(dim=-1, keepdims=True)
    v_nrmchmprtsub = v_chmprtsub / (v_prtsub + 1e-50)
    kappa_prt1 = (v_nrmchmprtsub * kappa_chmsub).sum(axis=-1)
    return torch.where(v_prtsub.squeeze(-1) > 0, kappa_prt1, void_kappa)


@torch.no_grad()
def clean_hist(
    m_chmprthst: torch.Tensor,
    n_prthst: torch.Tensor,
    n_seeds: int,
    n_mb: int,
    n_chem: int,
    n_bins: int,
) -> Tuple[torch.Tensor, torch.Tensor]:
    n_prthst = n_prthst.detach().clone()
    m_chmprthst = m_chmprthst.detach().clone()
    n_prthst[n_prthst < 0] = 0
    m_chmprthst = torch.where(n_prthst > 0, m_chmprthst, 0.0)
    m_chmprthst[m_chmprthst < 0] = 0
    m_prthst = m_chmprthst.sum(dim=-2, keepdims=True)
    n_prthst[m_prthst == 0.0] = 0.0
    return m_chmprthst, n_prthst


@torch.no_grad()
def clean_prtcls(
    m_prtchm: torch.Tensor,
    n_prt: torch.Tensor,
    n_seeds: int,
    n_mb: int,
    n_part: int,
    n_chem: int,
) -> Tuple[torch.Tensor, torch.Tensor]:
    n_prt = n_prt.detach().clone()
    m_prtchm = m_prtchm.detach().clone()
    n_prt[n_prt < 0] = 0
    m_prtchm = torch.where(n_prt > 0, m_prtchm, 0.0)
    m_prtchm[m_prtchm < 0] = 0
    m_prt = m_prtchm.sum(dim=-1, keepdims=True)
    n_prt[m_prt == 0.0] = 0.0
    return m_prtchm, n_prt


@torch.no_grad()
def cnvrt_hist2prtcls(
    m_chmprthst: torch.Tensor,
    n_prthst: torch.Tensor,
    n_seeds: int,
    n_mb: int,
    n_chem: int,
    n_bins: int,
) -> Tuple[torch.Tensor, torch.Tensor, int, int]:
    m_chmprthst, n_prthst = clean_hist(m_chmprthst, n_prthst, n_seeds, n_mb, n_chem, n_bins)
    n_partset = n_seeds * n_mb
    n_part = n_bins
    n_prt = n_prthst.flatten(0, 2)
    m_chmprtnet = m_chmprthst.flatten(0, 1).transpose(-1, -2)
    m_chmprt = torch.where(n_prt.unsqueeze(-1) > 0, m_chmprtnet / (n_prt.unsqueeze(-1) + 1e-50), 0.0)
    return m_chmprt, n_prt, n_partset, n_part


@torch.no_grad()
def calc_crh(
    m_chmprt: torch.Tensor,
    n_prt: torch.Tensor,
    tmprtr: torch.Tensor,
    rho_chm: torch.Tensor,
    kappa_chm: torch.Tensor,
    chem_species: List[str],
    n_partset: int,
    n_part: int,
    n_chem: int,
    void_kappa: float = 0.0,
    n_rfiters: int = 100,
    e_rfiters: float = 1e-12,
    strict: bool = False,
) -> Dict[str, torch.Tensor]:
    i_drychms = [i for i, chem in enumerate(chem_species) if chem != "H2O"]
    n_chemdry = n_chem - 1
    m_chmprtdry = m_chmprt[:, :, i_drychms]
    m_prtdry = m_chmprtdry.sum(dim=-1)
    kappa_chmdry = kappa_chm[i_drychms]
    rho_chmdry = rho_chm[i_drychms]
    v_chmprtdry = m_chmprtdry / rho_chmdry.reshape(1, 1, n_chemdry)
    v_prtdry = v_chmprtdry.sum(axis=-1)
    d_prtdry = (6 * v_prtdry / math.pi) ** (1 / 3)
    v_chmprt = m_chmprt / rho_chm.reshape(1, 1, n_chem)
    v_prt = v_chmprt.sum(axis=-1)
    d_prt = (6 * v_prt / math.pi) ** (1 / 3)
    v_nrmchmprtdry = v_chmprtdry / (v_prtdry.unsqueeze(-1) + 1e-50)
    kappa_prt1 = (v_nrmchmprtdry * kappa_chmdry.reshape(1, 1, n_chemdry)).sum(axis=-1)
    kappa_prt2 = torch.where(n_prt > 0, kappa_prt1, void_kappa)
    kappa_prt = torch.where(m_prtdry > 0, kappa_prt2, void_kappa)

    water_surf_eng = 0.073
    water_molec_weight = 18e-3
    univ_gas_const = 8.314472
    water_density = 1e3
    a_num = 4.0 * water_surf_eng * water_molec_weight
    a_denom = univ_gas_const * water_density * tmprtr.unsqueeze(-1)
    a_partset = a_num / a_denom
    c4 = -3.0 * (d_prtdry ** 3) * kappa_prt / a_partset
    c3 = -(d_prtdry ** 3) * (2.0 - kappa_prt)
    c0 = (d_prtdry ** 6) * (1.0 - kappa_prt)
    d_prtcrt1 = torch.pow((-4.0 / 3.0) * c4, 0.5)
    d_prtcrt2 = torch.pow(-c3, 1.0 / 3.0)
    d_prtcrt = torch.where(d_prtcrt1 > d_prtcrt2, d_prtcrt1, d_prtcrt2)
    is_kappaprttiny = kappa_prt < 1e-30
    for _ in range(n_rfiters):
        y_prt = (d_prtcrt ** 6) + c4 * (d_prtcrt ** 4) + c3 * (d_prtcrt ** 3) + c0
        dy_prt = 6 * (d_prtcrt ** 5) + 4 * c4 * (d_prtcrt ** 3) + 3 * c3 * (d_prtcrt ** 2)
        delta_y = y_prt / (dy_prt + 1e-50)
        deltay_rel = (delta_y / (d_prtcrt + 1e-50)).abs()
        has_converged1 = deltay_rel < e_rfiters
        d_prtcrt = torch.where(has_converged1, d_prtcrt, d_prtcrt - delta_y)
        has_converged2 = has_converged1.clone()
        has_converged2[is_kappaprttiny] = True
        if has_converged2.all():
            break
    d_prtcrt = torch.where(kappa_prt < 1e-30, d_prtdry, d_prtcrt)
    d_prtcrt = torch.where(d_prtdry > 0, d_prtcrt, 0.0)
    crh_prtnum1 = (d_prtcrt ** 3) - (d_prtdry ** 3)
    crh_prtdenom = (d_prtcrt ** 3) - (d_prtdry ** 3) * (1 - kappa_prt)
    crh_prtfrac = torch.where(kappa_prt < 1e-30, 1.0, crh_prtnum1 / (crh_prtdenom + 1e-50))
    crh_prtnum2 = (a_partset / (d_prtcrt + 1e-50)).exp()
    crh_prt = crh_prtfrac * crh_prtnum2
    crh_prt[crh_prtnum2.isinf()] = float("inf")
    crh_prt = torch.clamp(crh_prt, min=1.0)
    return {"d_prtdry": d_prtdry, "d_prt": d_prt, "kappa_prt": kappa_prt, "d_prtcrt": d_prtcrt, "crh_prt": crh_prt}


@torch.no_grad()
def calc_ccncdf(
    crh_prt: torch.Tensor,
    n_prt: torch.Tensor,
    n_partset: int,
    n_part: int,
    eps_histmin: float,
    eps_histmax: float,
    n_epshist: int,
    tch_device: torch.device,
    tch_dtype: torch.dtype,
) -> Dict[str, torch.Tensor]:
    eps_prt = crh_prt - 1
    ias_eps = eps_prt.argsort(axis=-1)
    eps_prtsrtd = torch.take_along_dim(eps_prt, ias_eps, dim=-1)
    n_prtsrtd = torch.take_along_dim(n_prt, ias_eps, dim=-1)
    n_prtsrtdcs = n_prtsrtd.cumsum(dim=-1)
    eps_histbins = torch.linspace(math.log(eps_histmin), math.log(eps_histmax), n_epshist, device=tch_device, dtype=tch_dtype).exp()
    eps_histbins2 = eps_histbins.reshape(1, n_epshist).expand(n_partset, n_epshist).contiguous()
    i_srchsrtdprt1 = torch.searchsorted(eps_prtsrtd, eps_histbins2, right=True)
    i_srchsrtdprt2 = torch.where(i_srchsrtdprt1 > 0, i_srchsrtdprt1 - 1, 0)
    ccn_cdf = torch.take_along_dim(n_prtsrtdcs, i_srchsrtdprt2, dim=-1) / (n_prtsrtdcs[:, -1:] + 1e-50)
    return {"eps_histbins": eps_histbins, "ccn_cdf": ccn_cdf}


@torch.no_grad()
def get_apprxccncdf(
    m_input: torch.Tensor,
    n_input: torch.Tensor,
    eps_histmin: float,
    eps_histmax: float,
    n_epshist: int,
    tmprtr_sclr: float,
    rho_chm: torch.Tensor,
    kappa_chm: torch.Tensor,
    chem_species: List[str],
    void_kappa: float,
    n_rfiters: int,
    e_rfiters: float,
    n_seeds: int,
    n_mb: int,
    n_chem: int,
    n_part: int,
    tch_device: torch.device,
    tch_dtype: torch.dtype,
    input_type: str = "hst",
    strict: bool = False,
) -> Dict[str, torch.Tensor]:
    if input_type == "hst":
        m_chmprt, n_prt, n_partset, n_part = cnvrt_hist2prtcls(m_input, n_input, n_seeds, n_mb, n_chem, n_part)
    elif input_type == "prt":
        m_chmprt_, n_prt_ = clean_prtcls(m_input, n_input, n_seeds, n_mb, n_part, n_chem)
        n_partset = n_seeds * n_mb
        m_chmprt = m_chmprt_.flatten(0, 1)
        n_prt = n_prt_.flatten(0, 1).squeeze(-1)
    else:
        raise ValueError(f"Undefined input_type: {input_type}")
    tmprtr = torch.full((n_partset,), tmprtr_sclr, device=tch_device, dtype=tch_dtype)
    crh_info = calc_crh(
        m_chmprt, n_prt, tmprtr, rho_chm, kappa_chm, chem_species,
        n_partset, n_part, n_chem, void_kappa, n_rfiters, e_rfiters, strict,
    )
    ccncdf_info = calc_ccncdf(
        crh_info["crh_prt"], n_prt, n_partset, n_part,
        eps_histmin, eps_histmax, n_epshist, tch_device, tch_dtype,
    )
    ccncdf_info["n_partset"] = n_partset
    ccncdf_info["n_part"] = n_part
    return ccncdf_info


def get_dlnpsi(z: torch.Tensor, n_max: int, device: torch.device, cdtype: torch.dtype) -> torch.Tensor:
    z_shape = z.shape
    eta_p20 = torch.zeros(*z_shape, n_max + 20, device=device, dtype=cdtype)
    for n_now in range(n_max + 18, 0, -1):
        term1 = (n_now + 1) / z
        term2_inv = term1 + eta_p20[..., n_now + 1]
        eta_p20[..., n_now] = term1 - 1.0 / (term2_inv + 1e-50)
    return eta_p20[..., :n_max]


def get_dlnzeta(z: torch.Tensor, n_max: int, device: torch.device, cdtype: torch.dtype) -> torch.Tensor:
    z_shape = z.shape
    eta = torch.zeros(*z_shape, n_max, device=device, dtype=cdtype)
    eta[..., 0] = -1j
    for n_now in range(1, n_max):
        term1 = n_now / z
        term2_inv = term1 - eta[..., n_now - 1]
        eta[..., n_now] = -term1 + 1.0 / (term2_inv + 1e-50)
    return eta


def get_tup(
    z: torch.Tensor,
    dp: torch.Tensor,
    dz: torch.Tensor,
    device: torch.device,
    dtype: torch.dtype,
    cdtype: torch.dtype,
) -> torch.Tensor:
    *z_shape, n_max = dp.shape
    oz_shape = tuple(1 for _ in z_shape)
    n_arange1 = torch.arange(2, n_max, device=device, dtype=dtype)
    n_arange = n_arange1.reshape(*oz_shape, n_max - 2)
    alpha = torch.empty(*z_shape, n_max, device=device, dtype=cdtype)
    alpha[..., 0] = 1.0
    alpha[..., 1] = 0.5 + (0.5 * (z * 2j).exp() * (z + 1j) / (z - 1j + 1e-50))
    alpha[..., 2:] = (n_arange / z.unsqueeze(-1) - dp[..., 1:-1]) / (n_arange / z.unsqueeze(-1) - dz[..., 1:-1] + 1e-50)
    t_val = alpha.cumprod(dim=-1)
    t_val[..., 0] = 0
    return t_val


def get_qqg(
    a: torch.Tensor,
    b: torch.Tensor,
    x: torch.Tensor,
    device: torch.device,
    dtype: torch.dtype,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    *x_shape, n_max = a.shape
    ox_shape = tuple(1 for _ in x_shape)
    n_arange1 = torch.arange(1, n_max + 1, device=device, dtype=dtype)
    n_arange = n_arange1.reshape(*ox_shape, n_max)
    apb_real = a.real + b.real
    x_square = x.square()
    a2pb2_real = a.real.square() + b.real.square() + a.imag.square() + b.imag.square()
    qe = 2 * (apb_real * (2 * n_arange + 1)).sum(dim=-1) / (x_square + 1e-50)
    qs = 2 * (a2pb2_real * (2 * n_arange + 1)).sum(dim=-1) / (x_square + 1e-50)
    g = torch.zeros_like(qs)
    return qe, qs, g


def get_sphere(
    m: torch.Tensor,
    x: torch.Tensor,
    n_max: int,
    device: torch.device,
    dtype: torch.dtype,
    cdtype: torch.dtype,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    m_sgnd = m.real - 1j * m.imag.abs()
    m_unsqz = m_sgnd.unsqueeze(-1)
    dpx = get_dlnpsi(x, n_max, device, cdtype)
    dpmx = get_dlnpsi(m_sgnd * x, n_max, device, cdtype)
    dzx = get_dlnzeta(x, n_max, device, cdtype)
    t_val = get_tup(x, dpx, dzx, device, dtype, cdtype)
    an = (t_val * (m_unsqz * dpx - dpmx) / (m_unsqz * dzx - dpmx + 1e-50))[..., 1:]
    bn = (t_val * (dpx - m_unsqz * dpmx) / (dzx - m_unsqz * dpmx + 1e-50))[..., 1:]
    return get_qqg(an, bn, x, device, dtype)


def get_coreshellnonsphr(
    mc: torch.Tensor,
    ms: torch.Tensor,
    xc: torch.Tensor,
    xs: torch.Tensor,
    n_max: int,
    device: torch.device,
    dtype: torch.dtype,
    cdtype: torch.dtype,
    full: bool = False,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    x_shape = xc.shape
    ox_shape = tuple(1 for _ in x_shape)
    n_arange1 = torch.arange(n_max, device=device, dtype=dtype)
    n_arange = n_arange1.reshape(*ox_shape, n_max)
    mc = mc.real - 1j * mc.imag.abs()
    ms = ms.real - 1j * ms.imag.abs()
    ms_3d, xs_3d, mc_3d, xc_3d = ms.unsqueeze(-1), xs.unsqueeze(-1), mc.unsqueeze(-1), xc.unsqueeze(-1)
    d_pss = get_dlnpsi(ms * xs, n_max, device, cdtype)
    d_ps = get_dlnpsi(xs + 1j * 0, n_max, device, cdtype)
    d_pcc = get_dlnpsi(mc * xc, n_max, device, cdtype)
    d_psc = get_dlnpsi(ms * xc, n_max, device, cdtype)
    d_zss = get_dlnzeta(ms * xs, n_max, device, cdtype)
    d_zs = get_dlnzeta(xs + 1j * 0, n_max, device, cdtype)
    d_zsc = get_dlnzeta(ms * xc, n_max, device, cdtype)
    pso_zs = get_tup(xs, d_ps, d_zs, device, dtype, cdtype)
    alpha_pscopss = (d_pss + n_arange / (ms_3d * xs_3d + 1e-50)) / (d_psc + n_arange / (ms_3d * xc_3d + 1e-50))
    alpha_pscopss[..., 0] = ((torch.exp(-1j * ms * (xc + xs)) - torch.exp(1j * ms * (xc - xs))) / (torch.exp(-2 * 1j * ms * xs) - 1 + 1e-50))
    pscopss = alpha_pscopss.cumprod(dim=-1)
    alpha_zscpsc = 1.0 / ((d_zsc + n_arange / (ms_3d * xc_3d + 1e-50)) * (d_psc + n_arange / (ms_3d * xc_3d + 1e-50)))
    alpha_zscpsc[..., 0] = (1.0 - torch.exp(-2 * 1j * ms * xc)) / 2.0
    zscpsc = alpha_zscpsc.cumprod(dim=-1)
    alpha_zsspsc = 1.0 / ((d_zss + n_arange / (ms_3d * xs_3d + 1e-50)) * (d_psc + n_arange / (ms_3d * xc_3d + 1e-50)))
    alpha_zsspsc[..., 0] = -0.5 * (torch.exp(-1j * ms * (xs + xc)) - torch.exp(-1j * ms * (xs - xc)))
    zsspsc = alpha_zsspsc.cumprod(dim=-1)
    u_val = mc_3d * d_psc - ms_3d * d_pcc
    v_val = ms_3d * d_psc - mc_3d * d_pcc
    w_val = -1j * (pscopss * zsspsc - zscpsc)
    an = (pso_zs * ((d_pss - ms_3d * d_ps) * (mc_3d + u_val * w_val) - u_val * pscopss**2) / ((d_pss - ms_3d * d_zs) * (mc_3d + u_val * w_val) - u_val * pscopss**2 + 1e-50))[..., 1:]
    bn = (pso_zs * ((ms_3d * d_pss - d_ps) * (ms_3d + v_val * w_val) - ms_3d * v_val * pscopss**2) / ((ms_3d * d_pss - d_zs) * (ms_3d + v_val * w_val) - ms_3d * v_val * pscopss**2 + 1e-50))[..., 1:]
    return get_qqg(an, bn, xs, device, dtype)


def get_coreshell(
    mc: torch.Tensor,
    ms: torch.Tensor,
    xc: torch.Tensor,
    xs: torch.Tensor,
    n_max: int,
    device: torch.device,
    dtype: torch.dtype,
    cdtype: torch.dtype,
    void_qe: float = 0.0,
    void_qs: float = 0.0,
    void_g: float = 0.0,
) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    x_shape = xc.shape
    n_part = math.prod(x_shape)
    mc, ms, xc, xs = mc.ravel(), ms.ravel(), xc.ravel(), xs.ravel()
    i_void = xs <= 0
    i_rmng = i_void.logical_not()
    i_rayleigh = (xs < 0.001).logical_and(i_rmng)
    i_rmng = i_rmng.logical_and(i_rayleigh.logical_not())
    i_sphr1 = (mc == ms).logical_or((xc / (xs + 1e-50)) < 0.01).logical_and(i_rmng)
    i_rmng = i_rmng.logical_and(i_sphr1.logical_not())
    i_sphr2 = ((xc / (xs + 1e-50)) > 0.99).logical_and(i_rmng)
    i_rmng = i_rmng.logical_and(i_sphr2.logical_not())
    i_coreshl = i_rmng
    qe = torch.empty(n_part, device=device, dtype=dtype)
    qs = torch.empty(n_part, device=device, dtype=dtype)
    g = torch.empty(n_part, device=device, dtype=dtype)
    if i_void.any():
        qe[i_void] = void_qe
        qs[i_void] = void_qs
        g[i_void] = void_g
    if i_rayleigh.any():
        mc_rayl, ms_rayl, xc_rayl, xs_rayl = mc[i_rayleigh], ms[i_rayleigh], xc[i_rayleigh], xs[i_rayleigh]
        xc2xs_rayl = (xc_rayl / (xs_rayl + 1e-50)).pow(3.0)
        mcs_rayl = mc_rayl * xc2xs_rayl + ms_rayl * (1.0 - xc2xs_rayl)
        mcs_sqrayl = mcs_rayl.square()
        mratio_rayl = (mcs_sqrayl - 1.0) / (mcs_sqrayl + 2.0)
        qs_rayleigh = (8 / 3) * xs_rayl.pow(4) * mratio_rayl.abs().square()
        qa_rayleigh = 4 * xs_rayl * mratio_rayl.imag * (1 + (4 / 3) * xs_rayl.pow(3) * mratio_rayl.imag)
        qe[i_rayleigh] = qs_rayleigh + qa_rayleigh
        qs[i_rayleigh] = qs_rayleigh
        g[i_rayleigh] = 0.0
    if i_sphr1.any():
        qe_sphr1, qs_sphr1, g_sphr1 = get_sphere(ms[i_sphr1], xs[i_sphr1], n_max, device, dtype, cdtype)
        qe[i_sphr1] = qe_sphr1
        qs[i_sphr1] = qs_sphr1
        g[i_sphr1] = g_sphr1
    if i_sphr2.any():
        qe_sphr2, qs_sphr2, g_sphr2 = get_sphere(mc[i_sphr2], xs[i_sphr2], n_max, device, dtype, cdtype)
        qe[i_sphr2] = qe_sphr2
        qs[i_sphr2] = qs_sphr2
        g[i_sphr2] = g_sphr2
    if i_coreshl.any():
        qe_coreshl, qs_coreshl, g_coreshl = get_coreshellnonsphr(mc[i_coreshl], ms[i_coreshl], xc[i_coreshl], xs[i_coreshl], n_max, device, dtype, cdtype, full=False)
        qe[i_coreshl] = qe_coreshl
        qs[i_coreshl] = qs_coreshl
        g[i_coreshl] = g_coreshl
    return qe.reshape(x_shape), qs.reshape(x_shape), g.reshape(x_shape)


@torch.no_grad()
def get_bulkoptical(
    m_input: torch.Tensor,
    n_input: torch.Tensor,
    rho_chm: torch.Tensor,
    refr_wvchm: torch.Tensor,
    len_wv: torch.Tensor,
    n_max: int,
    void_refr: complex,
    chem_species: List[str],
    n_seeds: int,
    n_mb: int,
    n_chem: int,
    n_part: int,
    n_wave: int,
    tch_device: torch.device,
    tch_dtype: torch.dtype,
    tch_cdtype: torch.dtype,
    input_type: str = "hst",
) -> Dict[str, torch.Tensor]:
    if input_type == "hst":
        m_chmprt, n_prt, n_partset, n_part = cnvrt_hist2prtcls(m_input, n_input, n_seeds, n_mb, n_chem, n_part)
    elif input_type == "prt":
        m_chmprt_, n_prt_ = clean_prtcls(m_input, n_input, n_seeds, n_mb, n_part, n_chem)
        n_partset = n_seeds * n_mb
        m_chmprt = m_chmprt_.flatten(0, 1)
        n_prt = n_prt_.flatten(0, 1).squeeze(-1)
    else:
        raise ValueError(f"Undefined input_type: {input_type}")
    v_chmprt = m_chmprt / rho_chm.reshape(1, 1, n_chem)
    v_prt = v_chmprt.sum(axis=-1)
    d_prt = (6 * v_prt / math.pi).pow(1.0 / 3.0)
    chem_inccore = ["BC", "OIN"]
    i_chmcore, _ = get_chemsubidx(chem_inccore, None, chem_species, n_chem)
    v_wvchmprt = v_chmprt.reshape(n_partset, 1, n_part, n_chem).expand(n_partset, n_wave, n_part, n_chem)
    refr_prtcore = get_vwakappa(v_wvchmprt, refr_wvchm[None, :, None, :], n_chem, void_refr, i_chmcore)
    v_prtcore = v_chmprt[..., i_chmcore].sum(axis=-1)
    d_prtcore = (6 * v_prtcore / math.pi).pow(1.0 / 3.0)
    i_chmshl, _ = get_chemsubidx(None, chem_inccore, chem_species, n_chem)
    refr_prtshll = get_vwakappa(v_wvchmprt, refr_wvchm[None, :, None, :], n_chem, void_refr, i_chmshl)
    x_prtshll = d_prt[:, None, :] * (math.pi / len_wv[None, :, None])
    x_prtcore = d_prtcore[:, None, :] * (math.pi / len_wv[None, :, None])
    n_partset_wave = n_partset * n_wave
    refr_prtcore_flat = refr_prtcore.reshape(n_partset_wave, n_part)
    refr_prtshll_flat = refr_prtshll.reshape(n_partset_wave, n_part)
    x_prtcore_flat = x_prtcore.reshape(n_partset_wave, n_part)
    x_prtshll_flat = x_prtshll.reshape(n_partset_wave, n_part)
    qe_prt_flat = torch.zeros(n_partset_wave, n_part, device=tch_device, dtype=tch_dtype)
    qs_prt_flat = torch.zeros(n_partset_wave, n_part, device=tch_device, dtype=tch_dtype)
    g_prt_flat = torch.zeros(n_partset_wave, n_part, device=tch_device, dtype=tch_dtype)
    for i_now in range(n_partset_wave):
        qe_i, qs_i, g_i = get_coreshell(
            refr_prtcore_flat[i_now], refr_prtshll_flat[i_now],
            x_prtcore_flat[i_now], x_prtshll_flat[i_now],
            n_max, tch_device, tch_dtype, tch_cdtype,
        )
        qe_prt_flat[i_now] = qe_i
        qs_prt_flat[i_now] = qs_i
        g_prt_flat[i_now] = g_i
    qe_prt_ = qe_prt_flat.reshape(n_partset, n_wave, n_part)
    qs_prt_ = qs_prt_flat.reshape(n_partset, n_wave, n_part)
    qa_prt_ = qe_prt_ - qs_prt_
    crossec_prt = d_prt.square() * (math.pi / 4)
    qs_pop_ = (crossec_prt[:, None, :] * qs_prt_ * n_prt[:, None, :]).sum(dim=-1)
    qa_pop_ = (crossec_prt[:, None, :] * qa_prt_ * n_prt[:, None, :]).sum(dim=-1)
    return {"qs_pop": qs_pop_.reshape(n_seeds, n_mb, n_wave), "qa_pop": qa_pop_.reshape(n_seeds, n_mb, n_wave)}


@torch.no_grad()
def get_bulkfrznfrac(
    m_input: torch.Tensor,
    n_input: torch.Tensor,
    tmprtr_inpmin: float,
    tmprtr_inpmax: float,
    n_tmprtr: int,
    rho_chm: torch.Tensor,
    chem_species: List[str],
    n_seeds: int,
    n_mb: int,
    n_chem: int,
    n_part: int,
    input_type: str = "hst",
) -> Dict[str, torch.Tensor]:
    tch_device = m_input.device
    tch_dtype = m_input.dtype
    if input_type == "hst":
        m_chmprt, n_prt, n_partset, n_part = cnvrt_hist2prtcls(m_input, n_input, n_seeds, n_mb, n_chem, n_part)
    elif input_type == "prt":
        m_chmprt_, n_prt_ = clean_prtcls(m_input, n_input, n_seeds, n_mb, n_part, n_chem)
        n_partset = n_seeds * n_mb
        m_chmprt = m_chmprt_.flatten(0, 1)
        n_prt = n_prt_.flatten(0, 1).squeeze(dim=-1)
    else:
        raise ValueError(f"Undefined input_type: {input_type}")
    temprtr_bins = torch.linspace(tmprtr_inpmin, tmprtr_inpmax, n_tmprtr, device=tch_device, dtype=tch_dtype)
    v_chmprt = m_chmprt / rho_chm.reshape(1, 1, n_chem)
    v_prt = v_chmprt.sum(axis=-1) + 1e-50
    d_prt = (6 * v_prt / math.pi).pow(1.0 / 3.0)
    i_oin = chem_species.index("OIN")
    i_bc = chem_species.index("BC")
    surf_prt = math.pi * d_prt.square()
    surf_oin1 = surf_prt * (v_chmprt[..., i_oin] / v_prt).pow(2.0 / 3.0)
    surf_bc1 = surf_prt * (v_chmprt[..., i_bc] / v_prt).pow(2.0 / 3.0)
    ns_oin = (-0.517 * temprtr_bins + 8.934).exp()
    ns_bc = (1.844 - 0.687 * temprtr_bins - 0.00597 * temprtr_bins.square()).exp()
    surfns_oin = ns_oin.reshape(1, 1, n_tmprtr) * surf_oin1.reshape(n_partset, n_part, 1)
    surfns_bc = ns_bc.reshape(1, 1, n_tmprtr) * surf_bc1.reshape(n_partset, n_part, 1)
    frznfrac_prttmp = 1.0 - (-surfns_oin - surfns_bc).exp()
    n_prt_norm = n_prt / (n_prt.sum(dim=-1, keepdim=True) + 1e-30)
    frznfrac_tmp1 = torch.einsum("ijk,ij->ik", frznfrac_prttmp, n_prt_norm)
    frznfrac_tmp1[frznfrac_tmp1 <= 0.0] = 0.0
    return {"frznfrac_tmp": frznfrac_tmp1.reshape(n_seeds, n_mb, n_tmprtr), "temprtr_bins": temprtr_bins}


def compute_ccn_spectrum(
    m_chmprthst: torch.Tensor,
    n_prthst: torch.Tensor,
    chem_species: List[str],
    eps_histmin: float = 1e-3,
    eps_histmax: float = 1e-1,
    n_epshist: int = 100,
    tmprtr: float = 287.0,
    rho_chm: Optional[torch.Tensor] = None,
    kappa_chm: Optional[torch.Tensor] = None,
    void_kappa: float = 0.0,
    n_rfiters: int = 100,
    e_rfiters: float = 1e-12,
) -> Dict[str, torch.Tensor]:
    device = m_chmprthst.device
    dtype = m_chmprthst.dtype
    if m_chmprthst.ndim == 3:
        m_chmprthst = m_chmprthst.unsqueeze(0)
        n_prthst = n_prthst.unsqueeze(0)
    n_seeds, n_pop, n_chem, n_bins = m_chmprthst.shape
    if rho_chm is None:
        rho_chm = torch.tensor([DEFAULT_CHEM_DENSITY.get(chem, 1000.0) for chem in chem_species], device=device, dtype=dtype)
    if kappa_chm is None:
        kappa_chm = torch.tensor([DEFAULT_CHEM_KAPPA.get(chem, 0.0) for chem in chem_species], device=device, dtype=dtype)
    result = get_apprxccncdf(
        m_chmprthst, n_prthst, eps_histmin, eps_histmax, n_epshist, tmprtr,
        rho_chm, kappa_chm, chem_species, void_kappa, n_rfiters, e_rfiters,
        n_seeds, n_pop, n_chem, n_bins, device, dtype, input_type="hst", strict=False,
    )
    ccn_cdf = result["ccn_cdf"].reshape(n_pop, n_epshist) if n_seeds == 1 else result["ccn_cdf"].reshape(n_seeds, n_pop, n_epshist)
    return {"ccn_cdf": ccn_cdf, "eps_histbins": result["eps_histbins"]}


def compute_optical_spectrum(
    m_chmprthst: torch.Tensor,
    n_prthst: torch.Tensor,
    chem_species: List[str],
    wavelengths: Optional[List[float]] = None,
    rho_chm: Optional[torch.Tensor] = None,
    refr_wvchm: Optional[torch.Tensor] = None,
    n_max: int = 100,
) -> Dict[str, torch.Tensor]:
    device = m_chmprthst.device
    dtype = m_chmprthst.dtype
    cdtype = torch.complex128 if dtype == torch.float64 else torch.complex64
    if m_chmprthst.ndim == 3:
        m_chmprthst = m_chmprthst.unsqueeze(0)
        n_prthst = n_prthst.unsqueeze(0)
    n_seeds, n_pop, n_chem, n_bins = m_chmprthst.shape
    if wavelengths is None:
        wavelengths = WAVELENGTHS_M
    len_wv = torch.tensor(wavelengths, device=device, dtype=dtype)
    n_wave = len(wavelengths)
    if rho_chm is None:
        rho_chm = torch.tensor([DEFAULT_CHEM_DENSITY.get(chem, 1000.0) for chem in chem_species], device=device, dtype=dtype)
    if refr_wvchm is None:
        refr_list = [DEFAULT_CHEM_REFRACTIVE.get(chem, 1.5 + 0j) for chem in chem_species]
        refr_wvchm = torch.tensor(refr_list, device=device, dtype=cdtype).unsqueeze(-1).expand(n_chem, n_wave)
    else:
        refr_wvchm = refr_wvchm.to(device=device, dtype=cdtype)
    result = get_bulkoptical(
        m_chmprthst, n_prthst, rho_chm, refr_wvchm, len_wv, n_max, complex(1.5, 0.0),
        chem_species, n_seeds, n_pop, n_chem, n_bins, n_wave, device, dtype, cdtype, input_type="hst",
    )
    qs_pop = result["qs_pop"].squeeze(0) if n_seeds == 1 else result["qs_pop"]
    qa_pop = result["qa_pop"].squeeze(0) if n_seeds == 1 else result["qa_pop"]
    return {"qs_pop": qs_pop, "qa_pop": qa_pop}


def compute_frozen_fraction_spectrum(
    m_chmprthst: torch.Tensor,
    n_prthst: torch.Tensor,
    chem_species: List[str],
    tmprtr_inpmin: float = -40.0,
    tmprtr_inpmax: float = 0.0,
    n_tmprtr: int = 100,
    rho_chm: Optional[torch.Tensor] = None,
) -> Dict[str, torch.Tensor]:
    device = m_chmprthst.device
    dtype = m_chmprthst.dtype
    if m_chmprthst.ndim == 3:
        m_chmprthst = m_chmprthst.unsqueeze(0)
        n_prthst = n_prthst.unsqueeze(0)
    n_seeds, n_pop, n_chem, n_bins = m_chmprthst.shape
    if rho_chm is None:
        rho_chm = torch.tensor([DEFAULT_CHEM_DENSITY.get(chem, 1000.0) for chem in chem_species], device=device, dtype=dtype)
    result = get_bulkfrznfrac(
        m_chmprthst, n_prthst, tmprtr_inpmin, tmprtr_inpmax, n_tmprtr,
        rho_chm, chem_species, n_seeds, n_pop, n_chem, n_bins, input_type="hst",
    )
    frznfrac_tmp = result["frznfrac_tmp"].squeeze(0) if n_seeds == 1 else result["frznfrac_tmp"]
    return {"frznfrac_tmp": frznfrac_tmp, "temprtr_bins": result["temprtr_bins"]}


def load_histograms(input_file, species_select):
    with nc.Dataset(input_file) as ds:
        mass_bins = ds.variables["M"][:].filled(np.nan).astype(np.float64, copy=False)
        numconc_bins = ds.variables["N"][:].filled(np.nan).astype(np.float64, copy=False)
        bins_lb = ds.variables["logDp_bins_lb"][:].filled(np.nan).astype(np.float64, copy=False)
        bins_rb = ds.variables["logDp_bins_rb"][:].filled(np.nan).astype(np.float64, copy=False)
        species_names = ds.variables["species"].getncattr("names")

    if isinstance(species_names, str):
        species_names = [name.strip() for name in species_names.split(",")]

    if list(species_names) != list(species_select):
        raise ValueError(
            f"Input-file species do not match the script configuration: file={species_names}, expected={species_select}"
        )

    if mass_bins.shape[1] != len(species_select):
        raise ValueError(
            f"M species dimension mismatch: got={mass_bins.shape[1]}, expected={len(species_select)}"
        )
    if mass_bins.shape[2] != N_BINS or numconc_bins.shape[1] != N_BINS:
        raise ValueError(
            f"Bin-count mismatch: M={mass_bins.shape[2]}, N={numconc_bins.shape[1]}, expected={N_BINS}"
        )

    bins_bnd = np.concatenate([bins_lb, bins_rb[-1:]])
    return mass_bins, numconc_bins, bins_bnd


def compute_diagnostics(mass_bins, numconc_bins, species_select):
    total_samples = mass_bins.shape[0]
    batch_size = min(DIAGNOSTIC_BATCH_SIZE, total_samples)
    n_batches = math.ceil(total_samples / batch_size)
    refr_wvchm = torch.tensor(
        [[DEFAULT_CHEM_REFRACTIVE.get(spec, 1.5 + 0j) for spec in species_select] for _ in WAVELENGTHS_M],
        dtype=torch.complex128,
    )

    ccn_out = np.empty((total_samples, N_EPS), dtype=np.float32)
    qs_out = np.empty((total_samples, len(WAVELENGTHS_M)), dtype=np.float32)
    qa_out = np.empty((total_samples, len(WAVELENGTHS_M)), dtype=np.float32)
    frozen_out = np.empty((total_samples, N_FREEZE_TEMP), dtype=np.float32)
    eps_histbins = None
    temprtr_bins = None

    t0 = time.time()
    for i_batch, i_start in enumerate(range(0, total_samples, batch_size), start=1):
        i_end = min(i_start + batch_size, total_samples)
        progress_pct = 100.0 * i_end / total_samples
        elapsed_s = time.time() - t0
        print(
            f"[Diagnostics] Batch {i_batch}/{n_batches} | "
            f"samples {i_start}:{i_end} / {total_samples} | "
            f"{progress_pct:5.1f}% complete | elapsed {elapsed_s:7.1f} s"
        , flush=True)

        m_hist = torch.as_tensor(mass_bins[i_start:i_end], dtype=TORCH_DTYPE)
        n_hist = torch.as_tensor(numconc_bins[i_start:i_end, np.newaxis, :], dtype=TORCH_DTYPE)

        ccn = compute_ccn_spectrum(
            m_hist,
            n_hist,
            species_select,
            eps_histmin=CCN_EPS_MIN,
            eps_histmax=CCN_EPS_MAX,
            n_epshist=N_EPS,
            tmprtr=CCN_TEMPERATURE_K,
        )
        optical = compute_optical_spectrum(
            m_hist,
            n_hist,
            species_select,
            wavelengths=WAVELENGTHS_M,
            refr_wvchm=refr_wvchm,
        )
        frozen = compute_frozen_fraction_spectrum(
            m_hist,
            n_hist,
            species_select,
            tmprtr_inpmin=FREEZE_TEMP_MIN_C,
            tmprtr_inpmax=FREEZE_TEMP_MAX_C,
            n_tmprtr=N_FREEZE_TEMP,
        )

        ccn_out[i_start:i_end] = ccn["ccn_cdf"].detach().cpu().numpy().astype(np.float32, copy=False)
        qs_out[i_start:i_end] = optical["qs_pop"].detach().cpu().numpy().astype(np.float32, copy=False)
        qa_out[i_start:i_end] = optical["qa_pop"].detach().cpu().numpy().astype(np.float32, copy=False)
        frozen_out[i_start:i_end] = frozen["frznfrac_tmp"].detach().cpu().numpy().astype(np.float32, copy=False)

        if eps_histbins is None:
            eps_histbins = ccn["eps_histbins"].detach().cpu().numpy().astype(np.float32, copy=False)
        if temprtr_bins is None:
            temprtr_bins = frozen["temprtr_bins"].detach().cpu().numpy().astype(np.float32, copy=False)

    total_elapsed_s = time.time() - t0
    print(f"[Diagnostics] Completed {total_samples} samples in {total_elapsed_s:.1f} s", flush=True)

    return {
        "ccn_cdf": ccn_out,
        "eps_histbins": eps_histbins,
        "qs_pop": qs_out,
        "qa_pop": qa_out,
        "frznfrac_tmp": frozen_out,
        "temprtr_bins": temprtr_bins,
    }


def create_output_file(out_path, n_species):
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    if os.path.exists(out_path):
        os.remove(out_path)

    ncf = nc.Dataset(out_path, "w", format="NETCDF4")
    ncf.createDimension("samples", None)
    ncf.createDimension("species", n_species)
    ncf.createDimension("bins", N_BINS)
    ncf.createDimension("eps", N_EPS)
    ncf.createDimension("wavelength", len(WAVELENGTHS_M))
    ncf.createDimension("temperature", N_FREEZE_TEMP)

    ncv_sample = ncf.createVariable("sample_index", "i4", ("samples",))
    ncv_ccn = ncf.createVariable("ccn_cdf", "f4", ("samples", "eps"))
    ncv_eps = ncf.createVariable("eps_histbins", "f4", ("eps",))
    ncv_qs = ncf.createVariable("optical_scattering", "f4", ("samples", "wavelength"))
    ncv_qa = ncf.createVariable("optical_absorption", "f4", ("samples", "wavelength"))
    ncv_wavelength = ncf.createVariable("wavelength_m", "f4", ("wavelength",))
    ncv_frozen = ncf.createVariable("frozen_fraction", "f4", ("samples", "temperature"))
    ncv_temp = ncf.createVariable("temperature_C", "f4", ("temperature",))
    ncv_bins_lb = ncf.createVariable("logDp_bins_lb", "f8", ("bins",))
    ncv_bins_rb = ncf.createVariable("logDp_bins_rb", "f8", ("bins",))
    ncv_species = ncf.createVariable("species", "i4", ("species",))

    ncv_sample.long_name = "Sample index in aero_samples_Zheng_N1000.nc"
    ncv_ccn.long_name = "CCN cumulative distribution function"
    ncv_eps.long_name = "Supersaturation epsilon bins where epsilon = CRH - 1"
    ncv_qs.long_name = "Bulk optical scattering spectrum"
    ncv_qa.long_name = "Bulk optical absorption spectrum"
    ncv_wavelength.long_name = "Optical wavelength in meters"
    ncv_frozen.long_name = "Bulk frozen fraction spectrum"
    ncv_temp.long_name = "Temperature bins in Celsius"
    ncv_bins_lb.long_name = "Lower edge of log10 dry particle diameter bins"
    ncv_bins_rb.long_name = "Upper edge of log10 dry particle diameter bins"
    ncv_species.long_name = "Species indices"
    ncv_species.setncattr("names", ",".join(SPECIES_SELECT))

    ncv_wavelength[:] = np.asarray(WAVELENGTHS_M, dtype=np.float32)
    ncv_species[:] = np.arange(n_species, dtype=np.int32)

    ncf.title = "Aerosol diagnostic spectra derived from Zheng N1000 histogram aerosol states"
    ncf.input_data = INPUT_FILE
    ncf.note = "Computed directly from pre-binned histogram data generated by extract_X.py."

    return ncf


def main():
    out_path = os.path.join(OUT_DIR, OUT_FILE)
    mass_bins, numconc_bins, bins_bnd = load_histograms(INPUT_FILE, SPECIES_SELECT)
    n_sample = mass_bins.shape[0]

    print(f"Using histogram aerosol states from: {INPUT_FILE}", flush=True)
    print(f"Loaded {n_sample} samples", flush=True)
    print("Diagnostics will be computed directly from precomputed M and N histograms.", flush=True)
    print(f"Diagnostic batch size: {min(DIAGNOSTIC_BATCH_SIZE, n_sample)}", flush=True)
    print(f"Writing output to: {out_path}", flush=True)
    diagnostics = compute_diagnostics(mass_bins, numconc_bins, SPECIES_SELECT)

    ncf = create_output_file(out_path, len(SPECIES_SELECT))
    try:
        ncf.variables["sample_index"][:] = np.arange(n_sample, dtype=np.int32)
        ncf.variables["ccn_cdf"][:] = diagnostics["ccn_cdf"]
        ncf.variables["optical_scattering"][:] = diagnostics["qs_pop"]
        ncf.variables["optical_absorption"][:] = diagnostics["qa_pop"]
        ncf.variables["frozen_fraction"][:] = diagnostics["frznfrac_tmp"]
        ncf.variables["eps_histbins"][:] = diagnostics["eps_histbins"]
        ncf.variables["temperature_C"][:] = diagnostics["temprtr_bins"]
        ncf.variables["logDp_bins_lb"][:] = bins_bnd[:-1]
        ncf.variables["logDp_bins_rb"][:] = bins_bnd[1:]
    finally:
        ncf.close()

    print(f"Finished. Wrote {n_sample} samples to {out_path}", flush=True)


if __name__ == "__main__":
    main()
